def test_register_ignores_unmarked_class_and_static_methods(
    he_pm: PluginManager,
) -> None:
    """Undecorated classmethods/staticmethods carry no marker on either side."""

    class Plugin:
        @classmethod
        def not_a_hook_cm(cls) -> None: ...

        @staticmethod
        def not_a_hook_sm() -> None: ...

        @hookimpl
        def he_method1(self, arg: object) -> list[object]:
            return [arg]

    plugin = Plugin()
    assert he_pm.parse_hookimpl_opts(plugin, "not_a_hook_cm") is None
    assert he_pm.parse_hookimpl_opts(plugin, "not_a_hook_sm") is None

    he_pm.register(plugin)
    assert he_pm.hook.he_method1(arg=1) == [[1]]

def test_warn_when_deprecated_args_specified(recwarn) -> None:
    warning1 = DeprecationWarning("old1 is deprecated")
    warning2 = DeprecationWarning("old2 is deprecated")

    class Spec:
        @hookspec(
            warn_on_impl_args={
                "old1": warning1,
                "old2": warning2,
            },
        )
        def foo(self, old1, new, old2):
            raise NotImplementedError()

    class Plugin:
        @hookimpl
        def foo(self, old2, old1, new):
            raise NotImplementedError()

    pm = PluginManager(hookspec.project_name)
    pm.add_hookspecs(Spec)

    with pytest.warns(DeprecationWarning) as records:
        pm.register(Plugin())
    (record1, record2) = records
    assert record1.message is warning2
    assert record1.filename == Plugin.foo.__code__.co_filename
    assert record1.lineno == Plugin.foo.__code__.co_firstlineno
    assert record2.message is warning1
    assert record2.filename == Plugin.foo.__code__.co_filename
    assert record2.lineno == Plugin.foo.__code__.co_firstlineno
